assert s.count(old)==1
s=s.replace(old,'  <div class="imc-toolbar-anchor"><div class="imc-toolbar">\n'+old,1)
s=s.replace('  </nav>\n','  </nav>\n  <div class="imc-assistant-slot" aria-hidden="true"></div>\n  </div></div>\n',1)
