p=ROOT/paths[1];s=p.read_text();assert ".imc-toolbar-anchor" not in s
p.write_text(s+"\n/* The shared assistant occupies reserved chrome, clear of country research text. */\n.imc-toolbar-anchor{height:var(--imc-toolbar-height,54px);margin-bottom:28px}\n.imc-toolbar{display:flex;align-items:center;gap:16px;border-block:1px solid var(--line);background:var(--panel);min-height:54px;padding-right:6px}\n.imc-toolbar.is-stuck{position:fixed;top:0;left:var(--imc-toolbar-left);width:var(--imc-toolbar-width);z-index:120}\n.imc-toolbar .imc-nav{flex:1;min-width:0;border:0;margin:0}\n.imc-assistant-slot{flex:0 0 40px;width:40px;height:40px}\nbody[data-imc-assistant-dock] :is(#mmb-boot,#mmb-launch){top:var(--imc-assistant-top);left:var(--imc-assistant-left);right:auto;bottom:auto;width:40px;height:40px;padding:0;gap:0;justify-content:center;border:1px solid var(--line);border-radius:8px;background:var(--panel);box-shadow:none;backdrop-filter:none}\nbody[data-imc-assistant-dock] :is(#mmb-boot,#mmb-launch):hover{transform:none;background:var(--panel2);box-shadow:none}\nbody[data-imc-assistant-dock] :is(#mmb-boot,#mmb-launch)::before,\nbody[data-imc-assistant-dock] :is(#mmb-boot,#mmb-launch)::after,\nbody[data-imc-assistant-dock] :is(#mmb-boot,#mmb-launch) .lt,\nbody[data-imc-assistant-dock] :is(#mmb-boot,#mmb-launch) .mmb-orb::after{display:none}\nbody[data-imc-assistant-dock] :is(#mmb-boot,#mmb-launch) .mmb-orb{width:24px;height:24px;border-radius:0;background:none;box-shadow:none;animation:none}\nbody[data-imc-assistant-dock] :is(#mmb-boot,#mmb-launch) .mmb-orb svg{width:20px;height:20px;fill:var(--link);filter:none}\nbody[data-imc-assistant-dock] :is(#mmb-boot,#mmb-launch):focus-visible{outline:2px solid var(--ink-info,var(--info));outline-offset:2px}\n@media(max-width:600px){\n .imc-toolbar-anchor{height:var(--imc-toolbar-height,94px);margin-bottom:18px}\n .imc-toolbar{gap:8px;padding-right:4px}\n .imc-toolbar .imc-nav{column-gap:8px}\n}\n@media print{.imc-toolbar.is-stuck{position:static}}\n")
p=ROOT/paths[2];s=p.read_text();old='    var tools = document.getElementById("intl-analysis-tools");'
assert s.count(old)==1
p.write_text(s.replace(old,"    // Keep the existing shared assistant in reserved navigation space.\n    // Its DOM, lazy handover, language handling and focus owner stay untouched.\n    var toolbar = root.querySelector(\".imc-toolbar\");\n    var toolbarAnchor = root.querySelector(\".imc-toolbar-anchor\");\n    var assistantSlot = root.querySelector(\".imc-assistant-slot\");\n    if (toolbar && toolbarAnchor && assistantSlot) {\n      var dockFrame = 0;\n      function updateAssistantDock() {\n        dockFrame = 0;\n        var anchorBox = toolbarAnchor.getBoundingClientRect();\n        var chrome = document.documentElement;\n        chrome.style.setProperty(\"--imc-toolbar-left\", anchorBox.left + \"px\");\n        chrome.style.setProperty(\"--imc-toolbar-width\", anchorBox.width + \"px\");\n        toolbar.classList.toggle(\"is-stuck\", anchorBox.top <= 0);\n        chrome.style.setProperty(\"--imc-toolbar-height\", toolbar.getBoundingClientRect().height + \"px\");\n        var slotBox = assistantSlot.getBoundingClientRect();\n        chrome.style.setProperty(\"--imc-assistant-left\", slotBox.left + \"px\");\n        chrome.style.setProperty(\"--imc-assistant-top\", slotBox.top + \"px\");\n        document.body.dataset.imcAssistantDock = \"true\";\n        document.querySelectorAll(\"#mmb-boot, #mmb-launch\").forEach(function (launcher) {\n          launcher.title = launcher.getAttribute(\"aria-label\") || \"\";\n        });\n      }\n      function scheduleAssistantDock() {\n        if (!dockFrame) dockFrame = window.requestAnimationFrame(updateAssistantDock);\n      }\n      window.addEventListener(\"scroll\", scheduleAssistantDock, {passive: true});\n      window.addEventListener(\"resize\", scheduleAssistantDock);\n      document.addEventListener(\"langchange\", scheduleAssistantDock);\n      if (typeof ResizeObserver === \"function\") {\n        var toolbarResize = new ResizeObserver(scheduleAssistantDock);\n        toolbarResize.observe(toolbarAnchor);\n        toolbarResize.observe(toolbar);\n      }\n      // The bootstrap and full widget are mounted directly under body.\n      // Observing that handover does not watch chat content or move widget nodes.\n      var assistantMount = new MutationObserver(scheduleAssistantDock);\n      assistantMount.observe(document.body, {childList: true});\n      updateAssistantDock();\n    }\n"+old,1))
after={p:sha256((ROOT/p).read_bytes()).hexdigest() for p in paths}
record={"recorded_at":datetime.now(timezone.utc).isoformat(),"parent":"0be244ba05355f4260b28da89dac4587f5a772e4","finding":"VTC-004","before":before,"after":after,
"behavior":"Existing launcher remains in its original shared root. Only measured position places it in a reserved toolbar slot; an opaque toolbar stays at the top after scrolling. Shared lazy loading, translation, panel and focus logic are unchanged.","shared_source_changed":False}
target=RIG/"assistant_toolbar_source_repair.json";assert not target.exists();target.write_text(json.dumps(record,indent=2)+"\n")
